import { useEffect, useState } from "react";
import "../../css/admin/admin_dash.css";

const API_BASE_URL = "http://localhost:5001";

// true = แสดงข้อมูลเดโม่
// false = ใช้ข้อมูลจาก API จริง
const DEMO_MODE = true;

const STATUS_LABELS = {
  reserved: "รอดำเนินการ",
  confirmed: "ยืนยันแล้ว",
  checked_in: "เช็กอินแล้ว",
  completed: "เสร็จสิ้น",
  cancelled: "ยกเลิก",
  no_show: "ไม่มาเช็กอิน",
};

const STATUS_ORDER = [
  "reserved",
  "confirmed",
  "checked_in",
  "completed",
  "cancelled",
  "no_show",
];

const RANGE_OPTIONS = [
  { value: "7d", label: "7 วันล่าสุด" },
  { value: "30d", label: "30 วันล่าสุด" },
  { value: "month", label: "เดือนนี้" },
  { value: "year", label: "ปีนี้" },
];

const DEMO_SUMMARY = {
  totalRooms: 12,
  availableRooms: 10,
  totalUsers: 486,
  totalBookings: 324,
};

const DEMO_STATUS = {
  "7d": [
    { status: "reserved", count: 12 },
    { status: "confirmed", count: 24 },
    { status: "checked_in", count: 18 },
    { status: "completed", count: 86 },
    { status: "cancelled", count: 15 },
    { status: "no_show", count: 5 },
  ],
  "30d": [
    { status: "reserved", count: 32 },
    { status: "confirmed", count: 78 },
    { status: "checked_in", count: 61 },
    { status: "completed", count: 246 },
    { status: "cancelled", count: 43 },
    { status: "no_show", count: 12 },
  ],
  month: [
    { status: "reserved", count: 25 },
    { status: "confirmed", count: 65 },
    { status: "checked_in", count: 49 },
    { status: "completed", count: 198 },
    { status: "cancelled", count: 32 },
    { status: "no_show", count: 9 },
  ],
  year: [
    { status: "reserved", count: 180 },
    { status: "confirmed", count: 620 },
    { status: "checked_in", count: 485 },
    { status: "completed", count: 2180 },
    { status: "cancelled", count: 350 },
    { status: "no_show", count: 95 },
  ],
};

const DEMO_ROOMS = {
  "7d": [
    { room_id: 1, room_code: "111", room_name: "ห้อง 111", count: 38 },
    { room_id: 2, room_code: "213", room_name: "ห้อง 213", count: 31 },
    { room_id: 3, room_code: "306", room_name: "ห้อง 306", count: 27 },
    { room_id: 4, room_code: "301", room_name: "ห้อง 301", count: 19 },
    { room_id: 5, room_code: "302", room_name: "ห้อง 302", count: 14 },
  ],
  "30d": [
    { room_id: 1, room_code: "111", room_name: "ห้อง 111", count: 142 },
    { room_id: 2, room_code: "213", room_name: "ห้อง 213", count: 118 },
    { room_id: 3, room_code: "306", room_name: "ห้อง 306", count: 96 },
    { room_id: 4, room_code: "301", room_name: "ห้อง 301", count: 75 },
    { room_id: 5, room_code: "302", room_name: "ห้อง 302", count: 62 },
  ],
  month: [
    { room_id: 1, room_code: "111", room_name: "ห้อง 111", count: 105 },
    { room_id: 2, room_code: "213", room_name: "ห้อง 213", count: 87 },
    { room_id: 3, room_code: "306", room_name: "ห้อง 306", count: 73 },
    { room_id: 4, room_code: "301", room_name: "ห้อง 301", count: 58 },
    { room_id: 5, room_code: "302", room_name: "ห้อง 302", count: 44 },
  ],
  year: [
    { room_id: 1, room_code: "111", room_name: "ห้อง 111", count: 680 },
    { room_id: 2, room_code: "213", room_name: "ห้อง 213", count: 542 },
    { room_id: 3, room_code: "306", room_name: "ห้อง 306", count: 431 },
    { room_id: 4, room_code: "301", room_name: "ห้อง 301", count: 320 },
    { room_id: 5, room_code: "302", room_name: "ห้อง 302", count: 268 },
  ],
};

const DEMO_PEAK = {
  "7d": [
    { label: "10:00–12:00 น.", count: 32 },
    { label: "14:00–16:00 น.", count: 25 },
    { label: "12:00–14:00 น.", count: 21 },
    { label: "08:00–10:00 น.", count: 18 },
  ],
  "30d": [
    { label: "10:00–12:00 น.", count: 128 },
    { label: "14:00–16:00 น.", count: 96 },
    { label: "12:00–14:00 น.", count: 84 },
    { label: "08:00–10:00 น.", count: 72 },
  ],
  month: [
    { label: "10:00–12:00 น.", count: 105 },
    { label: "14:00–16:00 น.", count: 81 },
    { label: "12:00–14:00 น.", count: 69 },
    { label: "08:00–10:00 น.", count: 58 },
  ],
  year: [
    { label: "10:00–12:00 น.", count: 720 },
    { label: "14:00–16:00 น.", count: 560 },
    { label: "12:00–14:00 น.", count: 430 },
    { label: "08:00–10:00 น.", count: 380 },
  ],
};

function getBangkokDate() {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: "Asia/Bangkok",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(new Date());

  const values = Object.fromEntries(
    parts.map((part) => [part.type, part.value])
  );

  return `${values.year}-${values.month}-${values.day}`;
}

function formatDate(dateString) {
  if (!dateString) return "-";

  const date = new Date(
    `${String(dateString).slice(0, 10)}T00:00:00+07:00`
  );

  if (Number.isNaN(date.getTime())) return String(dateString);

  return new Intl.DateTimeFormat("th-TH", {
    day: "numeric",
    month: "long",
    year: "numeric",
    timeZone: "Asia/Bangkok",
  }).format(date);
}

function formatTime(time) {
  return time ? String(time).slice(0, 5) : "-";
}

function formatNumber(value) {
  return Number(value || 0).toLocaleString("th-TH");
}

function getPercent(value, total) {
  if (!total) return 0;
  return Math.round((Number(value || 0) / total) * 100);
}

function getRangeLabel(range) {
  return (
    RANGE_OPTIONS.find((option) => option.value === range)?.label || ""
  );
}

function getDemoTodayBookings() {
  const today = getBangkokDate();

  return [
    {
      booking_id: "DEMO-001",
      booking_date: today,
      room_code: "111",
      room_name: "ห้องบรรยาย 111",
      user_name: "นางสาวกมลชนก ใจดี",
      start_time: "08:00:00",
      end_time: "10:00:00",
      status: "completed",
      purpose: "ประชุมกลุ่มโครงงาน",
    },
    {
      booking_id: "DEMO-002",
      booking_date: today,
      room_code: "213",
      room_name: "ห้องประชุม 213",
      user_name: "นายธนกร แสงทอง",
      start_time: "10:00:00",
      end_time: "12:00:00",
      status: "checked_in",
      purpose: "ประชุมทีม",
    },
    {
      booking_id: "DEMO-003",
      booking_date: today,
      room_code: "306",
      room_name: "ห้องบรรยาย 306",
      user_name: "นางสาวพิมพ์ชนก สุขใจ",
      start_time: "13:00:00",
      end_time: "15:00:00",
      status: "confirmed",
      purpose: "ติวหนังสือ",
    },
    {
      booking_id: "DEMO-004",
      booking_date: today,
      room_code: "301",
      room_name: "ห้องประชุม 301",
      user_name: "นายปกรณ์ วัฒนะ",
      start_time: "14:00:00",
      end_time: "16:00:00",
      status: "reserved",
      purpose: "ทำงานกลุ่ม",
    },
  ];
}

function DemoRangeSelect({ label, value, onChange }) {
  return (
    <select
      className="admin-range-select"
      aria-label={label}
      value={value}
      onChange={(event) => onChange(event.target.value)}
    >
      {RANGE_OPTIONS.map((option) => (
        <option key={option.value} value={option.value}>
          {option.label}
        </option>
      ))}
    </select>
  );
}

function AdminDashboard() {
  const [dashboard, setDashboard] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const [statusRange, setStatusRange] = useState("7d");
  const [roomsRange, setRoomsRange] = useState("7d");
  const [peakRange, setPeakRange] = useState("7d");

  const [statusData, setStatusData] = useState([]);
  const [roomsData, setRoomsData] = useState([]);
  const [peakData, setPeakData] = useState([]);

  const [statusLoading, setStatusLoading] = useState(false);
  const [roomsLoading, setRoomsLoading] = useState(false);
  const [peakLoading, setPeakLoading] = useState(false);

  const [statusError, setStatusError] = useState("");
  const [roomsError, setRoomsError] = useState("");
  const [peakError, setPeakError] = useState("");

  useEffect(() => {
    if (DEMO_MODE) {
      setDashboard({
        success: true,
        date: getBangkokDate(),
        summary: {
          ...DEMO_SUMMARY,
          todayBookingsCount: getDemoTodayBookings().length,
        },
        todayBookings: getDemoTodayBookings(),
      });
      setStatusData(DEMO_STATUS[statusRange]);
      setRoomsData(DEMO_ROOMS[roomsRange]);
      setPeakData(DEMO_PEAK[peakRange]);
      setLoading(false);
      return;
    }

    const controller = new AbortController();

    async function loadDashboard() {
      const token = localStorage.getItem("token");

      if (!token) {
        setError("ไม่พบ Token กรุณาเข้าสู่ระบบใหม่");
        setLoading(false);
        return;
      }

      try {
        setLoading(true);
        setError("");

        const response = await fetch(
          `${API_BASE_URL}/api/admin/dashboard`,
          {
            headers: {
              Authorization: `Bearer ${token}`,
              Accept: "application/json",
            },
            signal: controller.signal,
          }
        );

        const result = await response.json().catch(() => ({}));

        if (!response.ok || !result.success) {
          throw new Error(
            result.message || "ไม่สามารถโหลดข้อมูล Dashboard ได้"
          );
        }

        setDashboard(result);
      } catch (err) {
        if (err.name !== "AbortError") {
          setError(err.message || "เกิดข้อผิดพลาดในการเชื่อมต่อเซิร์ฟเวอร์");
        }
      } finally {
        if (!controller.signal.aborted) setLoading(false);
      }
    }

    loadDashboard();

    return () => controller.abort();
  }, []);

  useEffect(() => {
    if (DEMO_MODE) {
      setStatusData(DEMO_STATUS[statusRange]);
      return;
    }

    loadAnalytics("status", statusRange, {
      setLoading: setStatusLoading,
      setError: setStatusError,
      setData: setStatusData,
    });
  }, [statusRange]);

  useEffect(() => {
    if (DEMO_MODE) {
      setRoomsData(DEMO_ROOMS[roomsRange]);
      return;
    }

    loadAnalytics("popular-rooms", roomsRange, {
      setLoading: setRoomsLoading,
      setError: setRoomsError,
      setData: setRoomsData,
    });
  }, [roomsRange]);

  useEffect(() => {
    if (DEMO_MODE) {
      setPeakData(DEMO_PEAK[peakRange]);
      return;
    }

    loadAnalytics("peak-times", peakRange, {
      setLoading: setPeakLoading,
      setError: setPeakError,
      setData: setPeakData,
    });
  }, [peakRange]);

  async function loadAnalytics(type, range, setters) {
    const token = localStorage.getItem("token");

    if (!token) {
      setters.setError("ไม่พบ Token กรุณาเข้าสู่ระบบใหม่");
      setters.setData([]);
      return;
    }

    try {
      setters.setLoading(true);
      setters.setError("");

      const query = new URLSearchParams({ range });

      const response = await fetch(
        `${API_BASE_URL}/api/admin/analytics/${type}?${query}`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
            Accept: "application/json",
          },
        }
      );

      const result = await response.json().catch(() => ({}));

      if (!response.ok || !result.success) {
        throw new Error(
          result.message || "ไม่สามารถโหลดข้อมูลวิเคราะห์ได้"
        );
      }

      setters.setData(Array.isArray(result.data) ? result.data : []);
    } catch (err) {
      setters.setData([]);
      setters.setError(err.message || "เกิดข้อผิดพลาดในการโหลดข้อมูล");
    } finally {
      setters.setLoading(false);
    }
  }

  const summary = dashboard?.summary || {};
  const todayBookings = dashboard?.todayBookings || [];

  const cards = [
    {
      key: "rooms",
      label: "ห้องประชุมทั้งหมด",
      value: summary.totalRooms,
      detail: `เปิดให้บริการ ${formatNumber(summary.availableRooms)} ห้อง`,
      icon: "▤",
      className: "rooms",
    },
    {
      key: "users",
      label: "ผู้ใช้งานทั้งหมด",
      value: summary.totalUsers,
      detail: "นักศึกษาและอาจารย์",
      icon: "♙",
      className: "users",
    },
    {
      key: "bookings",
      label: "การจองทั้งหมด",
      value: summary.totalBookings,
      detail: "รายการจองในระบบ",
      icon: "▣",
      className: "bookings",
    },
    {
      key: "today",
      label: "การจองวันนี้",
      value: summary.todayBookingsCount,
      detail: "รายการตามวันที่ประเทศไทย",
      icon: "◷",
      className: "today",
    },
  ];

  const statusTotal = statusData.reduce(
    (sum, item) => sum + Number(item.count || 0),
    0
  );

  const maxRoom = Math.max(
    ...roomsData.map((item) => Number(item.count || 0)),
    1
  );

  const maxPeak = Math.max(
    ...peakData.map((item) => Number(item.count || 0)),
    1
  );

  return (
    <main className="admin-dashboard">
      {DEMO_MODE && (
        <div
          style={{
            marginBottom: 16,
            padding: "12px 16px",
            borderRadius: 10,
            background: "#fff4e8",
            color: "#995326",
            border: "1px solid #ffd8b5",
            fontSize: 14,
          }}
        >
          <strong>โหมดข้อมูลเดโม่</strong>
          {" — "}
          ตัวเลขและรายการจองเป็นข้อมูลจำลอง ไม่ใช่ข้อมูลจริงในฐานข้อมูล
        </div>
      )}

      <section className="admin-dashboard-intro">
        <div>
          <p className="admin-eyebrow">SYSTEM OVERVIEW</p>
          <h2>ภาพรวมระบบ</h2>
          <p className="admin-dashboard-description">
            ตรวจสอบและวิเคราะห์การใช้ห้องประชุม Booking CSTU
          </p>
        </div>

        <div className="admin-dashboard-date">
          <span>วันที่ข้อมูล</span>
          <strong>
            {dashboard ? formatDate(dashboard.date) : "กำลังโหลด..."}
          </strong>
        </div>
      </section>

      {error && (
        <section className="admin-dashboard-error" role="alert">
          <strong>โหลดข้อมูล Dashboard ไม่สำเร็จ</strong>
          <p>{error}</p>
          <button
            type="button"
            onClick={() => window.location.reload()}
          >
            ลองอีกครั้ง
          </button>
        </section>
      )}

      <section
        className="admin-dashboard-cards"
        aria-label="สรุปข้อมูลระบบ"
      >
        {cards.map((card) => (
          <article
            className={`admin-stat-card ${card.className}`}
            key={card.key}
          >
            <div className="admin-stat-card-top">
              <span className="admin-stat-label">{card.label}</span>
              <span className="admin-stat-icon" aria-hidden="true">
                {card.icon}
              </span>
            </div>

            <div className="admin-stat-value">
              {loading || error ? "—" : formatNumber(card.value)}
            </div>

            <p className="admin-stat-detail">
              {loading ? "กำลังโหลดข้อมูล..." : card.detail}
            </p>
          </article>
        ))}
      </section>

      <section className="admin-dashboard-section-heading">
        <div>
          <p className="admin-eyebrow">BOOKING ANALYTICS</p>
          <h2>วิเคราะห์การจอง</h2>
        </div>
      </section>

      <section className="admin-dashboard-panel">
        <div className="admin-panel-heading admin-filter-heading">
          <div>
            <h2>สถานะการจอง</h2>
            <p>สรุปจำนวนรายการจองตามสถานะในช่วงเวลาที่เลือก</p>
          </div>

          <DemoRangeSelect
            label="ช่วงเวลาสถานะการจอง"
            value={statusRange}
            onChange={setStatusRange}
          />
        </div>

        {statusLoading ? (
          <div className="admin-dashboard-message">กำลังโหลดข้อมูล...</div>
        ) : statusError ? (
          <div className="admin-dashboard-message">{statusError}</div>
        ) : (
          <>
            <div className="admin-status-total">
              <span>รายการจองในช่วง {getRangeLabel(statusRange)}</span>
              <strong>{formatNumber(statusTotal)}</strong>
            </div>

            <div className="admin-status-grid">
              {STATUS_ORDER.map((status) => {
                const item = statusData.find(
                  (row) => row.status === status
                );
                const count = Number(item?.count || 0);

                return (
                  <div className="admin-status-item" key={status}>
                    <div className="admin-status-item-heading">
                      <span className="admin-status-name">
                        <span className={`admin-status-dot status-${status}`} />
                        {STATUS_LABELS[status]}
                      </span>
                      <strong>{formatNumber(count)}</strong>
                    </div>

                    <div className="admin-status-track">
                      <div
                        className={`admin-status-fill status-${status}`}
                        style={{
                          width: `${getPercent(count, statusTotal)}%`,
                        }}
                      />
                    </div>

                    <span className="admin-status-percent">
                      {getPercent(count, statusTotal)}%
                    </span>
                  </div>
                );
              })}
            </div>
          </>
        )}
      </section>

      <section className="admin-analytics-grid">
        <article className="admin-dashboard-panel">
          <div className="admin-panel-heading admin-filter-heading">
            <div>
              <h2>ห้องยอดนิยม</h2>
              <p>จัดอันดับห้องตามจำนวนการจอง</p>
            </div>

            <DemoRangeSelect
              label="ช่วงเวลาห้องยอดนิยม"
              value={roomsRange}
              onChange={setRoomsRange}
            />
          </div>

          {roomsLoading ? (
            <div className="admin-dashboard-message">กำลังโหลดข้อมูล...</div>
          ) : roomsError ? (
            <div className="admin-dashboard-message">{roomsError}</div>
          ) : roomsData.length === 0 ? (
            <div className="admin-dashboard-message">
              ไม่พบรายการจองในช่วงเวลานี้
            </div>
          ) : (
            <div className="admin-ranking-list">
              {roomsData.map((room, index) => (
                <div className="admin-ranking-item" key={room.room_id}>
                  <span className="admin-ranking-number">{index + 1}</span>

                  <div className="admin-ranking-content">
                    <div className="admin-ranking-label">
                      <strong>{room.room_name || room.room_code}</strong>
                      <span>{formatNumber(room.count)} ครั้ง</span>
                    </div>

                    <div className="admin-ranking-track">
                      <div
                        className="admin-ranking-fill"
                        style={{
                          width: `${(Number(room.count || 0) / maxRoom) * 100}%`,
                        }}
                      />
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </article>

        <article className="admin-dashboard-panel">
          <div className="admin-panel-heading admin-filter-heading">
            <div>
              <h2>ช่วงเวลาที่มีการจองสูง</h2>
              <p>จำนวนรายการจองจำแนกตามช่วงเวลา</p>
            </div>

            <DemoRangeSelect
              label="ช่วงเวลาวิเคราะห์ช่วงเวลาการจอง"
              value={peakRange}
              onChange={setPeakRange}
            />
          </div>

          {peakLoading ? (
            <div className="admin-dashboard-message">กำลังโหลดข้อมูล...</div>
          ) : peakError ? (
            <div className="admin-dashboard-message">{peakError}</div>
          ) : peakData.length === 0 ? (
            <div className="admin-dashboard-message">
              ไม่พบรายการจองในช่วงเวลานี้
            </div>
          ) : (
            <div className="admin-ranking-list">
              {peakData.map((period, index) => (
                <div className="admin-ranking-item" key={period.label}>
                  <span className="admin-peak-icon">◷</span>

                  <div className="admin-ranking-content">
                    <div className="admin-ranking-label">
                      <strong>{period.label}</strong>
                      <span>{formatNumber(period.count)} ครั้ง</span>
                    </div>

                    <div className="admin-ranking-track">
                      <div
                        className="admin-ranking-fill peak"
                        style={{
                          width: `${(Number(period.count || 0) / maxPeak) * 100}%`,
                        }}
                      />
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </article>
      </section>

      <section className="admin-dashboard-panel admin-today-panel">
        <div className="admin-panel-heading">
          <div>
            <h2>รายการจองวันนี้</h2>
            <p>
              {dashboard
                ? formatDate(dashboard.date)
                : "รายการจองจากฐานข้อมูล"}
            </p>
          </div>

          <span className="admin-today-count">
            {loading
              ? "กำลังโหลด..."
              : `${formatNumber(todayBookings.length)} รายการ`}
          </span>
        </div>

        {loading ? (
          <div className="admin-dashboard-message">
            กำลังโหลดรายการจอง...
          </div>
        ) : error ? (
          <div className="admin-dashboard-message">
            ไม่สามารถโหลดรายการจองได้
          </div>
        ) : todayBookings.length === 0 ? (
          <div className="admin-dashboard-empty">
            <span className="admin-empty-icon" aria-hidden="true">▦</span>
            <strong>ไม่มีรายการจองวันนี้</strong>
            <p>ไม่พบรายการจองในวันที่แสดงอยู่</p>
          </div>
        ) : (
          <div className="admin-table-scroll">
            <table className="admin-dashboard-table">
              <thead>
                <tr>
                  <th>รหัสจอง</th>
                  <th>ห้องประชุม</th>
                  <th>ผู้จอง</th>
                  <th>เวลา</th>
                  <th>สถานะ</th>
                </tr>
              </thead>

              <tbody>
                {todayBookings.map((booking, index) => (
                  <tr key={booking.booking_id ?? index}>
                    <td className="admin-booking-id">
                      #{booking.booking_id}
                    </td>

                    <td>
                      <strong>{booking.room_code || "-"}</strong>
                      <span className="admin-table-secondary">
                        {booking.room_name || ""}
                      </span>
                    </td>

                    <td>{booking.user_name || "-"}</td>

                    <td className="admin-booking-time">
                      {formatTime(booking.start_time)}–
                      {formatTime(booking.end_time)}
                    </td>

                    <td>
                      <span
                        className={`admin-booking-status status-${booking.status}`}
                      >
                        {STATUS_LABELS[booking.status] || booking.status}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </main>
  );
}

export default AdminDashboard;
